from scipy.optimize import least_squares
def mm(S,Vm,Km): return Vm*S/(Km+S)
def fitm(name, f, p0):
    S=df.S.values; I=df.I.values; v=df.v.values
    best=None
    for s in range(20):
        p=np.array(p0)*np.exp(np.random.randn(len(p0))*0.5)
        try:
            r=least_squares(lambda q: f(S,I,q)-v, p, bounds=(1e-6,1e4))
        except Exception: continue
        if best is None or r.cost<best.cost: best=r
    n=len(v); k=len(p0); rss=2*best.cost
    bic=n*np.log(rss/n)+k*np.log(n); aic=n*np.log(rss/n)+2*k
    print(name, np.round(best.x,4), 'RSS',round(rss,4),'BIC',round(bic,2),'AIC',round(aic,2))
    return best
models={
